    para: `<p>NEET UG 2026 result is coming. Once it's out, counselling registration happens next. And this is where most candidates get confused.</p>

<p>People assume there's one counselling portal. There isn't. NEET UG admissions use three different counselling authorities depending on what course you want. This explains which portal you need, what each one does, fees, the process, and how they're different.</p>

<h4>One NEET Exam, Three Counselling Authorities</h4>

<table><tr><th>Authority</th><th>Courses</th><th>Portal</th></tr>
<tr><td>Medical Counselling Committee (MCC)</td><td>MBBS, BDS, BSc Nursing</td><td>mcc.nic.in</td></tr>
<tr><td>Ayush Admissions Central Counselling Committee (AACCC)</td><td>BAMS, BHMS, BUMS, BSMS</td><td>aaccc.gov.in</td></tr>
<tr><td>Veterinary Council of India (VCI)</td><td>BVSc & AH</td><td>vci.admissions.nic.in</td></tr>
</table>

<p>You need the right portal for your course. Each authority handles different admissions.</p>

<h4>Medical Counselling Committee (MCC)</h4>

<p>MCC handles admissions for MBBS, BDS, and BSc Nursing.</p>

<p><b>What They Manage</b></p>

<li>15% All India Quota (AIQ) seats in Government Medical Colleges</li>
<li>100% seats in AIIMS (all campuses)</li>
<li>JIPMER</li>
<li>Central Universities (BHU, AMU, DU, JMI)</li>
<li>ESIC Institutions</li>
<li>AFMC (separate admission process)</li>

<p>Overseen by Ministry of Health & Family Welfare.</p>

<p><b>When Counselling Happens:</b> Due to NEET UG 2026 re-exam, counselling expected between July and September 2026.</p>

<p><b>Counselling Rounds:</b> Round 1, Round 2, Round 3, Round 4, plus Stray Vacancy Round.</p>

<p><b>How to Register</b></p>

<li>Sign up on MCC portal with your NEET Roll Number</li>
<li>Pay registration fee and security deposit</li>
<li>Fill college and course preferences</li>
<li>Lock your choices before deadline</li>
<li>Check seat allotment result online</li>
<li>Report to your college with documents</li>

<p><b>Registration Fees for AIQ & Central University Seats</b></p>

<table><tr><th>Category</th><th>Registration Fee</th><th>Security Deposit</th></tr>
<tr><td>General / EWS</td><td>₹1,000</td><td>₹10,000</td></tr>
<tr><td>SC / ST / OBC / PwD</td><td>₹500</td><td>₹5,000</td></tr>
</table>

<p><b>For Deemed University Seats</b></p>

<table><tr><th>Category</th><th>Registration Fee</th><th>Security Deposit</th></tr>
<tr><td>All categories</td><td>₹5,000</td><td>₹2,00,000</td></tr>
</table>

<h4>Ayush Admissions Central Counselling Committee (AACCC)</h4>

<p>AACCC handles AYUSH courses: BAMS, BHMS, BUMS, BSMS, and B.Pharm (Ayurveda). Overseen by National Commission for Indian System of Medicine (NCISM), Ministry of Ayush.</p>

<p><b>What They Manage</b></p>

<li>15% All India Quota seats in Government and Aided AYUSH colleges</li>
<li>100% seats in Deemed Universities</li>
<li>Central Universities</li>
<li>National Institutes</li>
<li>Over 900 AYUSH colleges participate</li>

<p><b>When Counselling Happens:</b> Expected to start August 2026 (tentative).</p>

<p><b>Counselling Rounds:</b> Round 1, Round 2, Round 3, Stray Vacancy Round I, Stray Vacancy Round II.</p>

<p><b>Important AACCC Rules</b></p>

<li>Deemed University seats are unreserved. Central Government reservation policies don't apply.</li>
<li>Registration Fee: General ₹1,000, SC/ST ₹500.</li>
<li>No fresh registrations allowed during Stray Vacancy Round.</li>
<li>Candidates who don't join their allotted college lose security deposit and become ineligible for further rounds.</li>
<li>Foreign nationals applying under NRI quota in Deemed Universities don't need NEET for AYUSH UG courses.</li>

<h4>Veterinary Council of India (VCI)</h4>

<p>VCI handles counselling for BVSc & AH (Bachelor of Veterinary Science & Animal Husbandry).</p>

<p><b>Eligibility</b></p>

<li>Indian citizen</li>
<li>At least 17 years old by December 31, 2026</li>
<li>Qualified NEET UG 2026</li>

<p>Note: Jammu & Kashmir domicile candidates aren't eligible for AIQ seats.</p>

<p><b>Registration Fees</b></p>

<table><tr><th>Category</th><th>Registration Fee</th></tr>
<tr><td>General</td><td>₹1,000</td></tr>
<tr><td>EWS/OBC</td><td>₹900</td></tr>
<tr><td>SC/ST/PwD</td><td>₹500</td></tr>
</table>

<p><b>When Counselling Happens:</b> Expected September 2026.</p>

<p><b>Counselling Rounds:</b> Round 1, Round 2, Stray Vacancy Round.</p>

<h4>MCC vs AACCC vs VCI: Quick Comparison</h4>

<table><tr><th>Feature</th><th>MCC</th><th>AACCC</th><th>VCI</th></tr>
<tr><td>Courses</td><td>MBBS, BDS, BSc Nursing</td><td>BAMS, BHMS, BUMS, BSMS</td><td>BVSc & AH</td></tr>
<tr><td>AIQ Seats</td><td>15%</td><td>15%</td><td>15%</td></tr>
<tr><td>Deemed University Seats</td><td>Yes (100%)</td><td>Yes (100%)</td><td>No</td></tr>
<tr><td>Counselling Rounds</td><td>4 + Stray Vacancy</td><td>3 + Stray Vacancy I & II</td><td>2 + Stray Vacancy</td></tr>
<tr><td>Expected Start</td><td>July-September 2026</td><td>August 2026</td><td>September 2026</td></tr>
<tr><td>Conducting Ministry</td><td>Ministry of Health & Family Welfare</td><td>Ministry of Ayush</td><td>Department of Animal Husbandry & Dairying</td></tr>
<tr><td>Official Portal</td><td>mcc.nic.in</td><td>aaccc.gov.in</td><td>vci.admissions.nic.in</td></tr>
</table>

<h4>Final Thoughts</h4>

<p>You passed NEET UG 2026. That's step one. Now comes registering with the right counselling body based on what you want to study.</p>

<li>Want MBBS, BDS, or BSc Nursing? Go to MCC.</li>
<li>Interested in AYUSH - BAMS, BHMS, BUMS, BSMS? That's AACCC.</li>
<li>Looking at BVSc & AH? VCI is your place.</li>

<p>Get your documents together. Know the rules. Register before the deadlines close. This is where you actually secure a seat.</p>

<h4>FAQs</h4>

<p><b>Q: Which portal for MBBS counselling after NEET UG 2026?</b><br/>A: MCC handles it.</p>

<p><b>Q: Where do AYUSH aspirants sign up?</b><br/>A: AACCC.</p>

<p><b>Q: Who runs BVSc & AH counselling?</b><br/>A: VCI.</p>

<p><b>Q: Can I register for multiple counselling authorities?</b><br/>A: Yeah, if you're eligible for different courses.</p>

<p><b>Q: Is passing NEET UG enough to get a seat?</b><br/>A: No. You also have to register for counselling.</p>`,
